def render(payload: dict) -> str:
    players = payload["players"]
    calls = closest_calls(players, "half_ppr", context=DecisionContext(
        payload["mode"], payload["season"], "half_ppr", payload.get("week")))
    if not calls:
        raise ValueError("validated projections produced no closest calls")
    first = calls[0]
    first_a = first["winner"] or first["player_a"]
    first_b = first["runner_up"] or first["player_b"]
    for p in players:
        p["team_color"] = build_comparison_tool.TEAM_COLORS.get(
            p["team"], ("#263238", "#c6f53c"))[0]
    data = json.dumps(payload, separators=(",", ":")).replace("</", "<\\/")
    options = "".join(f'<option value="{esc(p["id"])}">{esc(player_label(p))}</option>'
                      for p in players)
    updated = payload["updated_at"]
    injuries_available = bool(
        (payload.get("sources") or {}).get("injuries", {}).get("updated_at")
    )
    injury_note = (
        "Current injury tags included. Q and D do not lower projections; "
        "confirmed unavailable players project for zero."
        if injuries_available else
        "Current injuries are not included. Check player status before kickoff."
    )
    faq_items = [
        ("How does LineupBeat choose a starter?", "The call starts with LineupBeat's Week 1 projection for each player. A recommendation appears only when the displayed difference clears our decision threshold."),
        ("Can the answer change by scoring format?", "Yes. Choose PPR, Half-PPR, or Non-PPR above. Reception value can change both the projected gap and the recommended player."),
        ("Does the comparison include current injuries?", (
            "Yes. Current injury tags are shown. Questionable and Doubtful do not lower projections; a confirmed unavailable status sets the Week 1 projection to zero."
            if injuries_available else
            "Not yet. Current injury reports are not included, so check each player's game status before kickoff."
        )),
        ("What is inside the full analysis?", "Open the full analysis to review each player's projection, opponent, expected opportunity, evidence agreement, and what could change the call."),
    ]
    faq_rows = "".join(
        f'<details><summary>{esc(question)}<span aria-hidden="true">+</span></summary><p>{esc(answer)}</p></details>'
        for question, answer in faq_items)
    faq_schema = json.dumps({
        "@context": "https://schema.org", "@type": "FAQPage",
        "mainEntity": [{"@type": "Question", "name": question,
                        "acceptedAnswer": {"@type": "Answer", "text": answer}}
                       for question, answer in faq_items],
    }, separators=(",", ":"))
